<script setup>import { reactive,ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../../stores/auth'; import AuthLayout from '../../layouts/AuthLayout.vue'; const router=useRouter(); const auth=useAuthStore(); const error=ref(''); const form=reactive({email:'',password:''}); const submit=async()=>{try{error.value=''; await auth.login(form); router.push('/dashboard')}catch(e){error.value=e.response?.data?.message||'Ошибка входа'}}</script><template><AuthLayout><h1 class="mt-6 text-3xl font-bold">Вход</h1><p class="mt-2 text-slate-500">Авторизуйтесь, чтобы управлять страницами памяти.</p><form class="mt-6 space-y-4" @submit.prevent="submit"><input class="input" v-model="form.email" placeholder="Email"><input class="input" v-model="form.password" type="password" placeholder="Пароль"><p v-if="error" class="text-sm text-red-600">{{ error }}</p><button class="btn-primary w-full">Войти</button></form><div class="mt-5 flex justify-between text-sm"><router-link class="font-semibold" to="/register">Регистрация</router-link><router-link class="text-slate-500" to="/forgot-password">Забыли пароль?</router-link></div></AuthLayout></template>
